#include <string>
#include <cmath>

class Solution {
public:
    int totalDistance(std::string word) {
        int total = 0;
        for (int i = 1; i < (int)word.length(); ++i) {
            int p1 = word[i - 1] - 'a', p2 = word[i] - 'a';
            total += std::abs(p1 / 6 - p2 / 6) + std::abs(p1 % 6 - p2 % 6);
        }
        return total;
    }
};

class Solution {
    public int totalDistance(String word) {
        int total = 0;
        for (int i = 1; i < word.length(); i++) {
            int p1 = word.charAt(i - 1) - 'a', p2 = word.charAt(i) - 'a';
            total += Math.abs(p1 / 6 - p2 / 6) + Math.abs(p1 % 6 - p2 % 6);
        }
        return total;
    }
}

function totalDistance(word) {
    let total = 0;
    for (let i = 1; i < word.length; i++) {
        const p1 = word.charCodeAt(i - 1) - 97;
        const p2 = word.charCodeAt(i) - 97;
        total += Math.abs(Math.floor(p1 / 6) - Math.floor(p2 / 6)) + Math.abs((p1 % 6) - (p2 % 6));
    }
    return total;
}
